/**
 * Phase 9 — real DEM patches at the mission sites (LOLA on the Moon, MOLA on Mars).
 *
 * Each mission site shipped with this build has a 256x256 16-bit grayscale PNG
 * patch generated by scripts/build-site-dems.py from NASA PDS elevation
 * products (see src/data/terrain/demCatalog.ts and the assets manifest). The
 * patch covers +-0.25 deg around the landing point (7.4-15 km). Inside its
 * core the height field IS the DEM (site-anchored, metres); approaching the
 * patch edge the DEM is faded out over a blend band and the procedural height
 * field (height.ts) takes over. The macroscale outside the data window is
 * reconstruction, and the UI says which is which (DataResolution).
 *
 * Decode path: the PNGs are bundled as base64 data URLs; fetch().arrayBuffer()
 * yields the bytes, which are parsed, unfiltered and inflated with
 * DecompressionStream. ImageBitmap/canvas decoders would truncate 16-bit
 * channels to 8 bits, so the decode is manual (~60 lines). Assets ship as
 * filter-0 PNGs we authored, but all five PNG filters are handled here so the
 * decoder stays honest for re-authored patches.
 */
import { SITE_DEM_CATALOG, type SiteDem } from "@/data/terrain/demCatalog";
import demApollo12 from "@/assets/terrain/dem/dem-apollo-12.png";
import demApollo14 from "@/assets/terrain/dem/dem-apollo-14.png";
import demApollo15 from "@/assets/terrain/dem/dem-apollo-15.png";
import demApollo16 from "@/assets/terrain/dem/dem-apollo-16.png";
import demApollo17 from "@/assets/terrain/dem/dem-apollo-17.png";
import demSojourner from "@/assets/terrain/dem/dem-sojourner.png";
import demSpirit from "@/assets/terrain/dem/dem-spirit.png";
import demOpportunity from "@/assets/terrain/dem/dem-opportunity.png";
import demInsight from "@/assets/terrain/dem/dem-insight.png";
import { useEcho } from "@/state/store";

const DEM_URLS: Record<string, string> = {
  "apollo-12": demApollo12,
  "apollo-14": demApollo14,
  "apollo-15": demApollo15,
  "apollo-16": demApollo16,
  "apollo-17": demApollo17,
  sojourner: demSojourner,
  spirit: demSpirit,
  opportunity: demOpportunity,
  insight: demInsight,
};

const R_M: Record<string, number> = { moon: 1737400, mars: 3396200 };

/** Blend band: DEM weight 1 inside coreFraction of the half-window, ->0 at the edge. */
const CORE_FRACTION = 0.88;

interface Patch {
  meta: SiteDem;
  /** grid x grid absolute metres. */
  h: Float32Array;
}

interface ActiveDem {
  patch: Patch | null;
  /** Site-anchored center height, subtracted so the landing point stays at y=0. */
  anchor: number;
  ready: boolean;
  loadToken: number;
}

const active: ActiveDem = { patch: null, anchor: 0, ready: false, loadToken: 0 };
const cache = new Map<string, Patch>();
let version = 0;
const listeners = new Set<() => void>();

/** Terrain phases subscribe to be told to invalidate cached geometry when the DEM lands. */
export function onDemReady(cb: () => void): () => void {
  listeners.add(cb);
  return () => listeners.delete(cb);
}

function fire() {
  version++;
  for (const l of listeners) l();
}

/* ---------------------------------------------------------------------------
 * PNG 16-bit grayscale decoder
 * ------------------------------------------------------------------------ */

async function decode16(url: string): Promise<{ w: number; h: number; data: Int16Array }> {
  const r = await fetch(url);
  const seed = new DataView(await r.arrayBuffer());
  if (seed.getUint32(0) !== 0x89504e47 || seed.getUint32(4) !== 0x0d0a1a0a) {
    throw new Error("bad png signature");
  }
  let pos = 8;
  let w = 0;
  let h = 0;
  const idat: Uint8Array[] = [];
  while (pos + 8 <= seed.byteLength) {
    const len = seed.getUint32(pos);
    const type = seed.getUint32(pos + 4);
    const where = pos + 8;
    if (type === 0x49484452) { // IHDR
      w = seed.getUint32(where);
      h = seed.getUint32(where + 4);
      const depth = seed.getUint8(where + 8);
      const color = seed.getUint8(where + 9);
      if (depth !== 16 || color !== 0) throw new Error("not 16-bit grayscale");
    } else if (type === 0x49444154) { // IDAT
      idat.push(new Uint8Array(seed.buffer.slice(where, where + len)));
    } else if (type === 0x49454e44) { // IEND
      break;
    }
    pos = where + len + 4;
  }
  if (!w || !h || !idat.length) throw new Error("png: missing chunks");
  const blob = new Blob(idat as BlobPart[]);
  const stream = blob.stream().pipeThrough(new DecompressionStream("deflate"));
  const raw = new Uint8Array(await new Response(stream).arrayBuffer());

  const stride = w * 2;
  if (raw.byteLength < h * (stride + 1)) throw new Error("png: truncated scanlines");
  const out = new Int16Array(w * h);
  const prev = new Uint8Array(stride);
  let p = 0;
  for (let yy = 0; yy < h; yy++) {
    const filter = raw[p++];
    const cur = raw.subarray(p, p + stride);
    p += stride;
    const recon = new Uint8Array(stride);
    for (let i = 0; i < stride; i++) {
      const a = i >= 2 ? recon[i - 2] : 0;
      const bb = prev[i];
      const c = i >= 2 ? prev[i - 2] : 0;
      let val = 0;
      switch (filter) {
        case 0: val = cur[i]; break;
        case 1: val = cur[i] + a; break;
        case 2: val = cur[i] + bb; break;
        case 3: val = cur[i] + ((a + bb) >> 1); break;
        case 4: {
          const cx = a + bb - c;
          const pa = Math.abs(cx - a), pb = Math.abs(cx - bb), pcn = Math.abs(cx - c);
          val = cur[i] + (pa <= pb && pa <= pcn ? a : pb <= pcn ? bb : c);
          break;
        }
        default: throw new Error(`png filter ${filter}`);
      }
      recon[i] = val & 0xff;
    }
    const dv = new DataView(recon.buffer, recon.byteOffset, stride);
    for (let xx = 0; xx < w; xx++) out[yy * w + xx] = dv.getInt16(xx * 2, false); // PNG is big-endian
    prev.set(recon);
  }
  if (p !== raw.byteLength) throw new Error("png: trailing bytes"); // we author exact-size streams
  return { w, h, data: out };
}

/* ---------------------------------------------------------------------------
 * Patch lifecycle
 * ------------------------------------------------------------------------ */

let seq = 0;

function setNote(n: string): void {
  useEcho.setState({ demNote: n });
}

function demLabel(meta: SiteDem): string {
  const kind = meta.world === "moon" ? "LOLA" : "MOLA";
  return `${kind} DEM ACTIVE · ${Math.round(meta.nativeGspM)} m NATIVE / ${Math.round(meta.deliveredGspM)} m SHOWN · MACRO RELIEF REAL`;
}

/** Load (or reuse the cached) DEM patch for a mission site. No-op for unknown sites. */
export async function loadSiteDem(siteId: string, world: "moon" | "mars"): Promise<boolean> {
  void world; // carried for future multi-body patches; the catalog is keyed by artifact id
  const meta = SITE_DEM_CATALOG.find((d) => d.artifactId === siteId);
  const url = DEM_URLS[siteId];
  if (!meta || !url) {
    setNote("");
    return false;
  }
  const token = ++seq;
  active.loadToken = token;
  if (cache.has(siteId)) {
    if (active.loadToken !== token) return false;
    usePatch(siteId);
    return true;
  }
  setNote(`${meta.product} — LOADING…`);
  active.ready = false;
  active.patch = null;
  try {
    const img = await decode16(url);
    if (img.w !== meta.grid || img.h !== meta.grid) throw new Error("patch size mismatch");
    const h = new Float32Array(meta.grid * meta.grid);
    for (let i = 0; i < h.length; i++) h[i] = img.data[i] * meta.hScale + meta.hOffsetM;
    cache.set(siteId, { meta, h });
    if (active.loadToken !== token) return false; // a newer site took over while decoding
    usePatch(siteId);
    return true;
  } catch (e) {
    console.error(`DEM load failed for ${siteId}`, e);
    if (active.loadToken === token) {
      setNote("DEM UNAVAILABLE — PROCEDURAL TERRAIN (SYNTHETIC RELIEF)");
      active.ready = false;
    }
    return false;
  }
}

export function clearSiteDem(): void {
  seq++;
  active.loadToken = seq;
  active.ready = false;
  active.patch = null;
  setNote("");
  fire();
}

function usePatch(siteId: string): void {
  const p = cache.get(siteId)!;
  active.patch = p;
  active.anchor = bilinear(p, p.meta.centerLat, p.meta.centerLonEast);
  active.ready = true;
  setNote(demLabel(p.meta));
  fire();
}

/* ---------------------------------------------------------------------------
 * Sampling: absolute metres from (lat, lon)
 * ------------------------------------------------------------------------ */

function bilinear(p: Patch, lat: number, lon: number): number {
  const g = p.meta.grid;
  const half = p.meta.patchHalfDeg;
  const ry = ((p.meta.centerLat + half - lat) / (2 * half)) * (g - 1); // rows run N->S
  const rx = ((lon - (p.meta.centerLonEast - half)) / (2 * half)) * (g - 1);
  const y0 = Math.min(g - 1, Math.max(0, Math.floor(ry)));
  const x0 = Math.min(g - 1, Math.max(0, Math.floor(rx)));
  const ty = Math.min(1, Math.max(0, ry - y0));
  const tx = Math.min(1, Math.max(0, rx - x0));
  const x1 = Math.min(g - 1, x0 + 1);
  const y1 = Math.min(g - 1, y0 + 1);
  const h00 = p.h[y0 * g + x0], h10 = p.h[y0 * g + x1], h01 = p.h[y1 * g + x0], h11 = p.h[y1 * g + x1];
  return (h00 * (1 - tx) + h10 * tx) * (1 - ty) + (h01 * (1 - tx) + h11 * tx) * ty;
}

/* ---------------------------------------------------------------------------
 * Engine seam (height.ts calls this for every vertex)
 * ------------------------------------------------------------------------ */

export interface DemSample {
  /** Patch height minus the landing-point height, metres. */
  h: number;
  /** Blend weight 1 (deep inside the patch) -> 0 (outside the window). */
  w: number;
}

/**
 * DEM contribution for site-local metres (x east, z south; the landing point
 * is the origin). Returns null when no patch is ready. bilinear() clamps
 * sampling at the edges, so far-field calls get edge heights with weight 0
 * and heightAt falls back to the procedural field there.
 */
export function demSample(x: number, z: number): DemSample | null {
  const p = active.patch;
  if (!p || !active.ready) return null;
  const rm = R_M[p.meta.world];
  const lat = p.meta.centerLat + (-z * 180) / (rm * Math.PI);
  const cosLat = Math.cos((lat * Math.PI) / 180);
  const lon = p.meta.centerLonEast + (x * 180) / (rm * Math.PI * cosLat);
  const dLat = (lat - p.meta.centerLat) / p.meta.patchHalfDeg;
  const dLon = (lon - p.meta.centerLonEast) / p.meta.patchHalfDeg;
  const maxDeg = Math.max(Math.abs(dLat), Math.abs(dLon));
  if (maxDeg > 1.001) return { h: 0, w: 0 };
  const w = maxDeg <= CORE_FRACTION ? 1 : 1 - (maxDeg - CORE_FRACTION) / (1 - CORE_FRACTION);
  return { h: bilinear(p, lat, lon) - active.anchor, w: Math.min(1, Math.max(0, w)) };
}

/** Current patch metadata for tests/harness introspection. */
export function demInfo(): { siteId: string | null; ready: boolean; version: number } {
  return { siteId: active.patch ? active.patch.meta.artifactId : null, ready: active.ready, version };
}

// Harness bridges (same pattern as __echoesAmb): verification reads DEM state.
declare global {
  interface Window {
    __echoesDemInfo?: typeof demInfo;
    __echoesDemNote?: () => string;
  }
}
if (typeof window !== "undefined") {
  window.__echoesDemInfo = demInfo;
  window.__echoesDemNote = () => useEcho.getState().demNote;
}
